#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>

static int count_above(const int *a,int n,int limit){
    int count=0;
    for(int i=0;i<n;++i) if(a[i]>limit) ++count;
    return count;
}
int main(void) {
int a[256]; int n;
if (scanf("%d", &n)!=1 || n<0 || n>256) return 1;
for(int i=0;i<n;++i) if(scanf("%d", &a[i])!=1) return 1;
int t;if(scanf("%d",&t)!=1)return 1;printf("%d\n",count_above(a,n,t));
return 0;
}
